import * as React from "react";
import { useState, useEffect, useMemo } from "react";
import { TextField } from "../textField";
import "./MultipleChoiceDropdown.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import InputChip from "../chips/Chips"
import { Checkbox } from "../checkbox";

export interface MultipleChoiceDropdownOption {
  value: string;
  label: string;
  icon?: keyof typeof SvgMpaIcon;
  iconColor?: string;
}

export interface MultipleChoiceDropdownProps {
  /**
   * Identifying value for the dropdown.
   */
  id: string;
  /**
   * Label to be displayed above the dropdown list.
   */
  label?: string;
  /**
   * List of dropdown options. Must be provided in a dictionary of key-value pairs.
   */
  options: MultipleChoiceDropdownOption[];
  /**
 * Property from MultipleChoiceDropdownOption to return from onChange. Defaults to value.
 */
  valueKey?: "label" | "value";
  /**
   * The initial value in the dropdown list.
   */
  selectedValues?: string[];
  /**
   * Custom onChange function that can be overrided.
   */
  onChange?: (values: string[]) => void;
  /**
   * Placeholder text to be displayed when no option is selected.
   */
  placeholder?: string;
  /**
   * Supporting text to display below the component.
   */
  supportingText?: string;
  /**
   * Text to display under the dropdown in case of an error.
   */
  errorText?: string;

  /**
   * Text to be displayed in a help tooltip next to the label.
   */
  tooltipText?: string;
   /**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?: "right" | "left" | "top" | "bottom";
   /**
    * React SVG icon object to be displayed in a help tooltip next to the label.
    */
  tooltipIcon?: keyof typeof SvgMpaIcon | string;

  /**
   * Boolean that determines if options can be searched.
   */
  searchable?: boolean;
  /**
   * Boolean that determines if a clear button appears when an option is selected.
   */
  clearable?: boolean;
  /**
   * Boolean that determines if the dropdown can be interacted with.
   */
  disabled?: boolean;
  /**
   * Boolean that determines if error styling is enabled.
   */
  error?: boolean;
  /**
   * Determines the colour palette of the dropdown.
   */

  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;
  /**
    * custom leading icon.
  */
  chipLeadingIcon?: keyof typeof SvgMpaIcon | any;
  /**
   * custom trailing icon.
   */
  chipTrailingIcon?: keyof typeof SvgMpaIcon | string;
  /**
   * custom trailing icon.
   */
  optionLeadingIcon?: keyof typeof SvgMpaIcon | string;
  /** 
   * Custom icon to always display in the dropdown header 
  */
  headerIcon?: keyof typeof SvgMpaIcon | string;
   /** 
    * If true, hides the selected values from the dropdown header 
   */
  hideSelectedInHeader?: boolean;
  /**
   * Width of the dropdown component (e.g., "200px", "100%", "20rem")
   */
  dropdownWidth?: string;
  /**
   Width of the dropdown options list (e.g., "200px", "20rem", "fit-content").
  If not provided, defaults to 100% of the trigger width.
  */
  dropdownListWidth?: string;
  /**
   * Boolean that determines if the dropdown options list should show a scrollbar when content overflows.
   * If false, the dropdown will expand to show all options without scrolling. Defaults to true.
   */
  enableDropDownScroll?: boolean;
  /**
   * Maximum height of the dropdown options list when scrolling is enabled (e.g., "200px", "15rem").
   * Only applies when enableScroll is true. Defaults to "200px".
   */
  maxHeight?: string;
}

const MultipleChoiceDropdown: React.FC<MultipleChoiceDropdownProps> = ({
  id,
  label,
  options = [], // Default to empty array
  valueKey = "value",
  selectedValues: initialSelectedValues = [],
  onChange,
  placeholder,
  supportingText,
  errorText,
  tooltipText,
  tooltipPlacement="top",
  tooltipIcon,
  disabled = false,
  error = false,
  clearable = false,
  searchable,
  colour = "primary",
  className,
  headerIcon,
  hideSelectedInHeader,
  chipLeadingIcon = "UserCircle",
  chipTrailingIcon = "X",
  optionLeadingIcon,
  dropdownWidth,
  dropdownListWidth,
  enableDropDownScroll = true,
  maxHeight = "200px"
}) => {
  const MAX_LABEL_LENGTH = 20;

  const [isOpen, setIsOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [internalSelectedValues, setInternalSelectedValues] = useState<string[]>(initialSelectedValues);

  const dropdownRef = React.useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    setInternalSelectedValues(initialSelectedValues);
  }, [initialSelectedValues]);

  const handleOptionClick = (
    option: MultipleChoiceDropdownOption,
    event: React.MouseEvent | React.ChangeEvent<HTMLInputElement>
  ) => {
    event.stopPropagation();
    const value = option[valueKey];
    const updatedValues = internalSelectedValues.includes(value)
      ? internalSelectedValues.filter(val => val !== value)
      : [...internalSelectedValues, value];

    onChange?.(updatedValues);
    setInternalSelectedValues(updatedValues);
  };

  const toggleDropdown = () => {
    if (!disabled) setIsOpen(prev => !prev);
  };

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(event.target.value);
  };

  const clearSelection = () => {
    onChange?.([]);
    setInternalSelectedValues([]);
    setSearchQuery("");
  };

  const truncateLabel = (label: string) =>
    label.length > MAX_LABEL_LENGTH ? `${label.substring(0, MAX_LABEL_LENGTH)}...` : label;

  const safeOptions = Array.isArray(options) ? options : [];

  const filteredOptions = useMemo(() => {
  return safeOptions.filter(option =>
    option.label.toLowerCase().includes(searchQuery.toLowerCase())
  );
}, [safeOptions, searchQuery]);

  const hoverclassName = `multiple-dropdown-text${isHovered ? "-hover" : ""}-${colour}`;
  const fontColor = `var(--mpa-fontColor-${colour})`;
  const dropdownStyle = dropdownWidth ? { width: dropdownWidth } : {};
  const dropdownListStyle = dropdownListWidth ? { width: dropdownListWidth } : { width: "100%" };

  const dropdownListScrollStyle = enableDropDownScroll 
    ? { maxHeight, overflowY: 'auto' as const }
    : { overflowY: 'visible' as const };

    const combinedDropdownListStyle = {
    ...dropdownListStyle,
    ...dropdownListScrollStyle
  };

  return (
    <div
      className={`dropdown container ${isOpen ? "expanded" : ""} ${className || ""}`}
      id={id}
      ref={dropdownRef}
    >
      <div className="form-dropdown">
        {label && (
          <div className="dropdown-label-div">
            <label className="dropdown-label">{label}</label>
            { tooltipText && tooltipText.trim().length > 0 && tooltipIcon && (
              <MpaIcon
                colour="var(--mpa-gray)"
                iconName={tooltipIcon}
                tooltipText={tooltipText}
                tooltipPlacement={tooltipPlacement}
              />
            )
            }
          </div>
        )}
        <div
          className={`multiple-dropdown-text ${disabled ? "dropdown-text-disabled" : ""} ${error ? "dropdown-text-error" : ""} ${internalSelectedValues.length > 0 ? "with-values" : ""} ${hoverclassName} ${headerIcon ? "header-icon-only" : ""}`}
          style={dropdownStyle}
          onClick={toggleDropdown}
          onFocus={() => setIsHovered(true)}
          onBlur={() => setIsHovered(false)}
        >
          {headerIcon ? (
            <span className="dropdown-header-icon">
              <MpaIcon iconName={headerIcon} />
            </span>
          ) : !hideSelectedInHeader && internalSelectedValues.length > 0 ? (
            <div className="div-input-inline">
              {internalSelectedValues.map(value => {
                const selectedOption = safeOptions?.find(option => option[valueKey] === value);
                return selectedOption ? (
                  <div key={value} className="inputChip-div">
                    <InputChip
                      id={value}
                      label={truncateLabel(selectedOption.label)}
                      colour={colour}
                      leadingIcon={selectedOption.icon && selectedOption.icon}
                      onClick={event => handleOptionClick(selectedOption, event)}
                    />
                  </div>
                ) : null;
              })}
            </div>
          ) : (
            placeholder
          )}
          {
          !headerIcon && (
            <div className="dropdown-icon-container">
                {clearable && internalSelectedValues.length > 0 && (
                  <span className="dropdown-clear-icon" onClick={clearSelection}>
                    <MpaIcon iconName="X" />
                  </span>
                )}
                <MpaIcon iconName={isOpen ? "ChevronUp" : "ChevronDown"} />
              </div>
          )
          }
        </div>
        {isOpen && (
          <div 
            className={`dropdown-options ${enableDropDownScroll ? 'with-scroll' : 'no-scroll'}`} 
            style={combinedDropdownListStyle}
          >
            {searchable && (
              <div className="search-input-container">
                <TextField
                  id="search-input"
                  type="text"
                  placeholder="Search"
                  leadingIcon="Search"
                  value={searchQuery}
                  onChange={handleSearchChange}
                  className="dropdown-search"
                  clearable
                />
              </div>
            )}
            <ul className="dropdown-list">
              {(searchQuery === "" ? safeOptions : filteredOptions).length === 0 ? (
                <li className="no-options">No options available</li>
              ) : (
                (searchQuery === "" ? safeOptions : filteredOptions).map(option => (
                  <li key={option.value} className="dropdown-item">
                    <Checkbox
                      colour={colour}
                      id={`checkbox-${option.value}`}
                      label={option.label}
                      className="dropdown-option-checkbox"
                      checked={internalSelectedValues.includes(option[valueKey])}
                      onChange={event => handleOptionClick(option, event)}
                    />

                    <span className="dropdown-option-icon-wrapper ${option.icon}">
                      {option.icon && <MpaIcon iconName={option.icon} colour={option.iconColor}/>}
                    </span>
                  </li>
                ))
              )}
            </ul>
          </div>
        )}
      </div>

      {supportingText && !error && !isOpen && (
        <div className="supporting-text">{supportingText}</div>
      )}
      {errorText && error && !isOpen && (
        <div className="error-text">
          <span className="dropdown-error-icon">
            <MpaIcon iconName="AlertCircle" />
          </span>
          {errorText}
        </div>
      )}
    </div>
  );
};

export default MultipleChoiceDropdown;


